from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
def main():
    result=ROOT/'reports/latest/results.json'
    if not result.exists():raise SystemExit('Run python run.py train first.')
    d=json.loads(result.read_text(encoding='utf-8')); s=d['sample']; m=d['disruption']; q=d['delay_q90']
    ops_path=ROOT/'reports/latest/operations_scenario.json'
    ops=json.loads(ops_path.read_text(encoding='utf-8')) if ops_path.exists() else None
    lines=['# Held-out findings','',f"June 2025 temporal holdout: {s['june_test_rows']:,} labeled flights; disruption prevalence {s['test_positive_rate']:.1%}.",'',
    '## Disruption model','',f"- Isotonic-calibrated LightGBM ROC AUC: {m['roc_auc']:.4f}; average precision: {m['average_precision']:.4f}.",
    f"- Brier score: {m['brier_score']:.5f}; preceding-28-day route-rate baseline: {m['baseline_route_28d_brier']:.5f}.",
    'The baseline comparison matters: a more complex model is useful only if it improves on simple recent route history. Isotonic calibration was fitted on May only; June was held out.','',
    '## Arrival-delay quantile','',f"The LightGBM q90 prediction received a May-only conformal correction of {q['calibration_offset_min']:.2f} minutes. On {q['rows']:,} completed, non-diverted June flights, coverage moved from {q['raw_empirical_coverage']:.1%} to {q['empirical_coverage']:.1%}; calibrated MAE is {q['mae']:.2f} minutes (raw: {q['raw_mae']:.2f}). May coverage after correction was {q['validation_coverage_after_calibration']:.1%}. June remains a temporal-shift check, not a guarantee of 90% future coverage.",'']
    if ops:
        sc=ops['scenario'];lines += ['## Network and buffer scenario','',f"On {ops['heldout_day']}, reconstructed {ops['plausible_same_tail_airport_turn_links']:,} plausible consecutive-flight links from pseudonymized aircraft identifiers. The descriptive correlation between preceding arrival delay and next-flight arrival delay was {ops['prior_arrival_vs_next_arrival_delay_correlation_descriptive']}.",
          f"The hypothetical {sc['assumed_total_buffer_budget_min']}-minute buffer scenario allocated {sc['allocated_min']} minutes across {sc['candidate_flights']} high-q90 flights. Mean modeled q90 was {sc['mean_q90_before_min']:.1f} minutes before and {sc['mean_q90_after_min']:.1f} after allocation, under the authored scenario objective. This is not a measured operational intervention.",'']
    lines += ['## Scope limits','',*['- '+x for x in d['limits']], '', 'See [full metrics](../reports/latest/results.json), [data and method](DATA_AND_METHOD.md), and [run instructions](../README.md).','']
    (ROOT/'docs/FINDINGS.md').write_text('\n'.join(lines),encoding='utf-8')
    # Portable, offline report with no tail hashes in the published output.
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Airline Disruption Analytics</title><style>body{{font:16px/1.6 system-ui;margin:0;background:#f4f7fa;color:#18334b}}header{{background:#153d52;color:#fff;padding:35px 7vw}}main{{max-width:950px;margin:28px auto;padding:0 20px}}section{{background:white;padding:22px;margin:18px 0;border-radius:12px;box-shadow:0 2px 12px #17324a12}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}}.card{{background:#eaf1f5;padding:16px;border-radius:10px}}b{{display:block;font-size:1.35em}}small{{text-transform:uppercase;letter-spacing:.08em}}a{{color:#087c91}}</style><header><small>U.S. BTS · JAN–JUN 2025</small><h1>Airline Disruption Analytics</h1><p>Chronological machine-learning evaluation, aircraft-turn analysis and a constrained buffer-allocation scenario.</p></header><main><section class="cards"><div class="card"><small>June labeled flights</small><b>{s['june_test_rows']:,}</b></div><div class="card"><small>Disruption ROC AUC</small><b>{m['roc_auc']:.3f}</b></div><div class="card"><small>Disruption average precision</small><b>{m['average_precision']:.3f}</b></div><div class="card"><small>q90 empirical coverage</small><b>{q['empirical_coverage']:.1%}</b></div></section><section><h2>What this demonstrates</h2><p>Scheduled flight, operator, route and calendar features combine with strictly lagged 28-day operating history. A LightGBM model estimates disruption risk; an isotonic mapping calibrated in May is evaluated in June. A separate quantile model estimates the 90th percentile of arrival delay for completed, non-diverted flights. A May-only conformal correction is frozen before June evaluation.</p><p>Brier score: <b>{m['brier_score']:.4f}</b>; 28-day route-history baseline: <b>{m['baseline_route_28d_brier']:.4f}</b>. q90 coverage before/after correction: <b>{q['raw_empirical_coverage']:.1%} / {q['empirical_coverage']:.1%}</b>; corrected MAE: <b>{q['mae']:.1f} minutes</b>.</p></section>{'<section><h2>Operations scenario</h2><p>'+str(ops['plausible_same_tail_airport_turn_links'])+' plausible tail rotation links were reconstructed. A hypothetical buffer-allocation scenario is documented in the findings.</p></section>' if ops else ''}<section><h2>Interpretation</h2><p>This is an analytical portfolio project using U.S. public data. The dataset has no weather forecasts, passenger itineraries, crews, gates, maintenance states or airline costs. The optimizer is a stated what-if exercise, not evidence of real-world savings or a dispatch recommendation.</p><p><a href="../../docs/FINDINGS.md">Findings</a> · <a href="../../docs/DATA_AND_METHOD.md">Data and method</a> · <a href="../../README.md">Run instructions</a> · <a href="results.json">Metrics JSON</a></p></section></main></html>'''
    (ROOT/'reports/latest/index.html').write_text(page,encoding='utf-8')
    print('Wrote offline HTML report and docs/FINDINGS.md')
if __name__=='__main__':main()
